import math
import ast
import json
import io
import contextlib
from typing import Any

async def calculator_tool(
    expression: str,
    precision:  int = 6,
) -> dict:
    """Safely evaluate mathematical expressions."""
    try:
        allowed = {
            k: v for k, v in math.__dict__.items()
            if not k.startswith("_")
        }
        allowed.update({
            "abs": abs, "round": round,
            "min": min, "max": max, "sum": sum,
        })
        result = eval(expression, {"__builtins__": {}}, allowed)
        return {
            "expression": expression,
            "result":     round(float(result), precision),
            "type":       type(result).__name__,
            "status":     "success",
        }
    except ZeroDivisionError:
        return {"error": "Division by zero", "expression": expression}
    except Exception as e:
        return {"error": str(e), "expression": expression}

async def code_executor_tool(
    code:     str,
    language: str = "python",
    timeout:  int = 10,
) -> dict:
    """Execute Python code in a sandboxed environment."""
    if language.lower() != "python":
        return {"error": f"Language '{language}' not supported. Only Python."}

    safe_globals: dict[str, Any] = {
        "__builtins__": {
            "print": print, "len": len, "range": range,
            "str": str, "int": int, "float": float,
            "list": list, "dict": dict, "tuple": tuple,
            "set": set, "bool": bool, "enumerate": enumerate,
            "zip": zip, "map": map, "filter": filter,
            "sorted": sorted, "sum": sum, "min": min,
            "max": max, "abs": abs, "round": round,
            "isinstance": isinstance, "type": type,
        },
        "math": math,
        "json": json,
    }

    stdout_buf = io.StringIO()
    error      = None

    try:
        with contextlib.redirect_stdout(stdout_buf):
            exec(compile(code, "<string>", "exec"), safe_globals)
        stdout = stdout_buf.getvalue()
        status = "success"
    except Exception as e:
        error  = str(e)
        stdout = stdout_buf.getvalue()
        status = "error"

    return {
        "code":    code[:300],
        "stdout":  stdout,
        "error":   error,
        "status":  status,
        "language": language,
    }

async def unit_converter_tool(
    value:     float,
    from_unit: str,
    to_unit:   str,
) -> dict:
    """Convert between measurement units."""
    conversions = {
        ("km",         "miles"):       0.621371,
        ("miles",      "km"):          1.60934,
        ("kg",         "pounds"):      2.20462,
        ("pounds",     "kg"):          0.453592,
        ("meters",     "feet"):        3.28084,
        ("feet",       "meters"):      0.3048,
        ("liters",     "gallons"):     0.264172,
        ("gallons",    "liters"):      3.78541,
        ("celsius",    "fahrenheit"):  None,   # Special formula
        ("fahrenheit", "celsius"):     None,
    }

    key = (from_unit.lower(), to_unit.lower())

    if key == ("celsius", "fahrenheit"):
        result = (value * 9/5) + 32
    elif key == ("fahrenheit", "celsius"):
        result = (value - 32) * 5/9
    elif key in conversions:
        result = value * conversions[key]
    else:
        return {
            "error":      f"Conversion {from_unit}→{to_unit} not supported",
            "supported":  list(set(f"{a}→{b}" for a,b in conversions.keys())),
        }

    return {
        "input":     {"value": value,           "unit": from_unit},
        "output":    {"value": round(result, 4), "unit": to_unit},
        "formula":   f"{value} {from_unit} = {round(result, 4)} {to_unit}",
        "status":    "success",
    }
